package com.colavite.gestor_investimento.controller;
import com.colavite.gestor_investimento.entity.*; import com.colavite.gestor_investimento.repository.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.MockMvc; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional class CarteiraPosicaoControllerTest { @Autowired MockMvc mockMvc; @Autowired CarteiraRepository carteiras; @Autowired AcaoRepository acoes; @Autowired OperacaoRepository operacoes;
 @Test void consultaPosicoesEResumo() throws Exception { var c=carteiras.saveAndFlush(new Carteira("Resumo","RESUMO",null)); var a=acoes.saveAndFlush(new Acao("PETR4","Petrobras",Mercado.BRASIL,new BigDecimal("12"),Instant.now())); operacoes.saveAndFlush(new Operacao(c,a,TipoOperacao.COMPRA,new BigDecimal("10"),new BigDecimal("10"),Instant.now())); mockMvc.perform(get("/carteiras/"+c.getId()+"/posicoes")).andExpect(status().isOk()).andExpect(jsonPath("$[0].quantidade").value(10)); mockMvc.perform(get("/carteiras/"+c.getId()+"/resumo")).andExpect(status().isOk()).andExpect(jsonPath("$.porMoeda.BRL.patrimonioAtual").value(120)); }
 @Test void carteiraInexistenteRetorna404() throws Exception { mockMvc.perform(get("/carteiras/999999/posicoes")).andExpect(status().isNotFound()); }
}
